    {
      "summary": "Both frozen obligations are introduced: each specific behavior is absent before and supported after, while the old harness cannot reach it.",
      "coverage_complete": false,
      "coverage_evidence": [],
      "claims": [
        {
          "claim_id": "c1",
          "necessary": "yes",
          "necessity_reason": "After the change, parse_ex supports rejecting a misplaced minus during saved-exponent continuation, but the fixed harness cannot make a continuation call.",
          "before": {
            "requirement": "Reject a misplaced minus using exponent state reconstructed from a previous parse_ex call.",
            "applicability": "not_applicable",
            "harness_status": "not_applicable",
            "reason": "The old number path initializes exponent state afresh on each call and has no saved-exponent reconstruction. Its generic minus check is a different behavior.",
            "source_evidence": [
              {"unit_id":"u-2d8ccbead426038a1615","start_line":833,"end_line":840,"role":"primary","dependency_reason":""},
              {"unit_id":"u-2d8ccbead426038a1615","start_line":863,"end_line":889,"role":"dependency","dependency_reason":"The old exponent and minus checks use only state from the current call."}
            ]
          },
          "after": {
            "requirement": "Reach saved-exponent reconstruction and reject a misplaced continuation minus on the same tokener.",
            "applicability": "required",
            "harness_status": "unsat",
            "reason": "The added reconstruction distinguishes an exponent already saved in the tokener, then the minus guard rejects the continuation. The harness calls parse_ex only once.",
            "source_evidence": [
              {"unit_id":"u-3825843bff0f16a3e325","start_line":835,"end_line":860,"role":"primary","dependency_reason":""},
              {"unit_id":"u-3825843bff0f16a3e325","start_line":898,"end_line":915,"role":"dependency","dependency_reason":"The reconstructed state determines the continuation minus error."},
              {"unit_id":"u-dd39172cb88171ba7e29","start_line":1,"end_line":2,"role":"dependency","dependency_reason":"The change log identifies the specific incremental rejection."}
            ]
          },
          "same_blocker": "not_applicable",
          "harness_evidence": [
            {"unit_id":"u-0d886f0f9ece675b0cbf","start_line":5,"end_line":12,"role":"primary","dependency_reason":""}
          ],
          "comparison_reason": "The one-call harness constraint existed on both sides, but the same saved-exponent rejection obligation did not exist before.",
          "missing_information": [],
          "change_ids": ["g0001","g0003","g0013","g0014"]
        },
        {
          "claim_id": "c2",
          "necessary": "yes",
          "necessity_reason": "After the change, strict mode rejects a missing exponent, but the fixed harness never enables strict mode.",
          "before": {
            "requirement": "Produce the strict-mode number error for an incomplete exponent such as \"[0e]\".",
            "applicability": "not_applicable",
            "harness_status": "not_applicable",
            "reason": "The old parser has no strict-specific incomplete-exponent rejection at number conversion; it passes the buffer to the old double parser instead.",
            "source_evidence": [
              {"unit_id":"u-2d8ccbead426038a1615","start_line":892,"end_line":902,"role":"primary","dependency_reason":""},
              {"unit_id":"u-2d8ccbead426038a1615","start_line":937,"end_line":947,"role":"dependency","dependency_reason":"The old double path does not test completeness under strict flags."}
            ]
          },
          "after": {
            "requirement": "Reach strict-mode rejection of the missing exponent in \"[0e]\".",
            "applicability": "required",
            "harness_status": "unsat",
            "reason": "The added trim applies only without JSON_TOKENER_STRICT; the supplied after cases specify success by default and a number error in strict mode. The harness has no flag-setting call.",
            "source_evidence": [
              {"unit_id":"u-3825843bff0f16a3e325","start_line":928,"end_line":943,"role":"primary","dependency_reason":""},
              {"unit_id":"u-3825843bff0f16a3e325","start_line":979,"end_line":991,"role":"dependency","dependency_reason":"The untrimmed strict number reaches the length-aware conversion and error path."},
              {"unit_id":"u-06d8630b3f2c38898d39","start_line":9,"end_line":10,"role":"dependency","dependency_reason":"The after test cases specify the distinct default and strict outcomes."}
            ]
          },
          "same_blocker": "not_applicable",
          "harness_evidence": [
            {"unit_id":"u-0d886f0f9ece675b0cbf","start_line":5,"end_line":12,"role":"primary","dependency_reason":""}
          ],
          "comparison_reason": "The default-only harness setup existed before, but the specific strict rejection of a missing exponent is supported only after the change.",
          "missing_information": [],
          "change_ids": ["g0001","g0007","g0013","g0014"]
        }
      ],
